135	impl Options {
136	    /// Parse the given iterator of command-line strings into an Options
137	    /// struct and a list of free filenames, using the environment variables
138	    /// for extra options.
139	    #[allow(unused_results)]
140	    pub fn parse<'args, I, V>(args: I, vars: &V) -> OptionsResult<'args>
141	    where
142	        I: IntoIterator<Item = &'args OsStr>,
143	        V: Vars,
144	    {
145	        use crate::options::parser::{Matches, Strictness};
146	
147	        #[rustfmt::skip]
148	        let strictness = match vars.get_with_fallback(vars::EZA_STRICT, vars::EXA_STRICT) {
149	            None                         => Strictness::UseLastArguments,
150	            Some(ref t) if t.is_empty()  => Strictness::UseLastArguments,
151	            Some(_)                      => Strictness::ComplainAboutRedundantArguments,
152	        };
153	
154	        let Matches { flags, frees } = match flags::ALL_ARGS.parse(args, strictness) {
155	            Ok(m) => m,
156	            Err(pe) => return OptionsResult::InvalidOptions(OptionsError::Parse(pe)),
157	        };
158	
159	        if let Some(help) = HelpString::deduce(&flags) {
160	            return OptionsResult::Help(help);
161	        }
162	
163	        if let Some(version) = VersionString::deduce(&flags) {
164	            return OptionsResult::Version(version);
165	        }
166	
167	        match Self::deduce(&flags, vars) {
168	            Ok(options) => OptionsResult::Ok(options, frees),
169	            Err(oe) => OptionsResult::InvalidOptions(oe),
170	        }
171	    }
172	
173	    /// Whether the View specified in this set of options includes a Git
174	    /// status column. It’s only worth trying to discover a repository if the
175	    /// results will end up being displayed.
176	    #[must_use]
177	    pub fn should_scan_for_git(&self) -> bool {
178	        if self.filter.git_ignore == GitIgnore::CheckAndIgnore {
179	            return true;
180	        }
181	
182	        match self.view.mode {
183	            Mode::Details(details::Options {
184	                table: Some(ref table),
185	                ..
186	            })
187	            | Mode::GridDetails(grid_details::Options {
188	                details:
189	                    details::Options {
190	                        table: Some(ref table),
191	                        ..
192	                    },
193	                ..
194	            }) => table.columns.git,
195	            _ => false,
196	        }
197	    }
198	
199	    /// Determines the complete set of options based on the given command-line
200	    /// arguments, after they’ve been parsed.
201	    fn deduce<V: Vars>(matches: &MatchedFlags<'_>, vars: &V) -> Result<Self, OptionsError> {
202	        if cfg!(not(feature = "git"))
203	            && matches
204	                .has_where_any(|f| f.matches(&flags::GIT) || f.matches(&flags::GIT_IGNORE))
205	                .is_some()
206	        {
207	            return Err(OptionsError::Unsupported(String::from(
208	                "Options --git and --git-ignore can't be used because `git` feature was disabled in this build of exa",
209	            )));
210	        }
211	        let view = View::deduce(matches, vars)?;
212	        let dir_action = DirAction::deduce(matches, matches!(view.mode, Mode::Details(_)))?;
213	        let filter = FileFilter::deduce(matches)?;
214	        let theme = ThemeOptions::deduce(matches, vars)?;
215	        let stdin = FilesInput::deduce(matches, vars)?;
216	
217	        Ok(Self {
218	            dir_action,
219	            filter,
220	            view,
221	            theme,
222	            stdin,
223	        })
224	    }
225	}
