407	    /// Determine which of a file’s time fields should be displayed for it
408	    /// based on the user’s options.
409	    ///
410	    /// There are two separate ways to pick which fields to show: with a
411	    /// flag (such as `--modified`) or with a parameter (such as
412	    /// `--time=modified`). An error is signaled if both ways are used.
413	    ///
414	    /// It’s valid to show more than one column by passing in more than one
415	    /// option, but passing *no* options means that the user just wants to
416	    /// see the default set.
417	    fn deduce(matches: &MatchedFlags<'_>) -> Result<Self, OptionsError> {
418	        let possible_word = matches.get(&flags::TIME)?;
419	        let modified = matches.has(&flags::MODIFIED)?;
420	        let changed = matches.has(&flags::CHANGED)?;
421	        let accessed = matches.has(&flags::ACCESSED)?;
422	        let created = matches.has(&flags::CREATED)?;
423	
424	        let no_time = matches.has(&flags::NO_TIME)?;
425	
426	        #[rustfmt::skip]
427	        let time_types = if no_time {
428	            Self {
429	                modified: false,
430	                changed: false,
431	                accessed: false,
432	                created: false,
433	            }
434	        } else if let Some(word) = possible_word {
435	            if modified {
436	                return Err(OptionsError::Useless(&flags::MODIFIED, true, &flags::TIME));
437	            } else if changed {
438	                return Err(OptionsError::Useless(&flags::CHANGED, true, &flags::TIME));
439	            } else if accessed {
440	                return Err(OptionsError::Useless(&flags::ACCESSED, true, &flags::TIME));
441	            } else if created {
442	                return Err(OptionsError::Useless(&flags::CREATED, true, &flags::TIME));
443	            } else if word == "mod" || word == "modified" {
444	                Self { modified: true,  changed: false, accessed: false, created: false }
445	            } else if word == "ch" || word == "changed" {
446	                Self { modified: false, changed: true,  accessed: false, created: false }
447	            } else if word == "acc" || word == "accessed" {
448	                Self { modified: false, changed: false, accessed: true,  created: false }
449	            } else if word == "cr" || word == "created" {
450	                Self { modified: false, changed: false, accessed: false, created: true  }
451	            } else {
452	                return Err(OptionsError::BadArgument(&flags::TIME, word.into()));
453	            }
454	        } else if modified || changed || accessed || created {
455	            Self {
456	                modified,
457	                changed,
458	                accessed,
459	                created,
460	            }
461	        } else {
462	            Self::default()
463	        };
464	
465	        Ok(time_types)
466	    }
467	}
